// Joint Trainer-Stammdaten in jeden Workshop und transformiert in das
// API-Response-Format, das index.html erwartet.
//
// Erwartetes Response-Shape pro Workshop:
//   { id, Name, Datum, LifoVerwendet, TrainerName, TrainerPhoto }
//
// SeaTable-Eigenheit: Link-Spalten sind is_multiple=true (lässt sich nicht
// abschalten), liefern also IMMER Arrays. Wir greifen Trainer[0].

const workshopsResp = $('Query Workshops (SQL)').first().json;
const trainersResp  = $('Query Trainer (SQL)').first().json;

const workshops = (workshopsResp && workshopsResp.results) || [];
const trainers  = (trainersResp  && trainersResp.results)  || [];

// Trainer-Lookup nach SeaTable-Row-ID
const trainersById = Object.create(null);
for (const t of trainers) {
  trainersById[t._id] = t;
}

// SeaTable-Link-Spalten kommen je nach Version als
//   ['rowid_abc', 'rowid_def']  ODER
//   [{row_id: 'rowid_abc', display_value: 'Anna Köhler'}, ...]
// Beide Formen abfangen.
function firstLinkedId(link) {
  if (!Array.isArray(link) || link.length === 0) return null;
  const first = link[0];
  if (typeof first === 'string') return first;
  if (first && typeof first === 'object' && first.row_id) return first.row_id;
  return null;
}

const out = workshops.map(ws => {
  const trainerId = firstLinkedId(ws.Trainer);
  const trainer   = trainerId ? trainersById[trainerId] : null;
  return {
    id:            ws._id,
    Name:          ws.Name || '',
    Datum:         ws.Datum || '',
    LifoVerwendet: !!ws.LifoVerwendet,
    TrainerName:   trainer ? (trainer.Name || '') : '',
    TrainerPhoto:  trainer ? (trainer.FotoUrl || '') : ''
  };
});

return [{ json: { workshops: out } }];
